// Independent packed truth evaluation. No producer headers, roots or transforms.
// The unchanged frozen basis-checking code is generated by build.py.
#include "build/certificate_helpers.inc"

struct Result {
    Certificate certificate;
    uint64_t zeta_words, coefficient_bits, scratch_bytes;
};

struct Workspace {
    uint32_t n, equations, limbs, universe, blocks;
    std::array<uint64_t, 64> low{};
    std::vector<uint64_t> values, roots;
    std::vector<uint8_t> present;
    Workspace(uint32_t variables, uint32_t count)
        : n(variables), equations(count), limbs((count + 63) / 64),
          universe(1u << variables), blocks((universe + 63) / 64),
          values(size_t(count) * blocks), roots(blocks), present(count)
    {
        for (uint32_t mask = 0; mask < 64; ++mask)
            for (uint32_t point = 0; point < 64; ++point)
                if ((point & mask) == mask) low[mask] |= uint64_t(1) << point;
    }
};

static void validate(const Workspace &w, const uint32_t *masks,
                     const uint64_t *coefficients, uint32_t count)
{
    if (count && (!masks || !coefficients)) throw std::invalid_argument("buffers");
    for (uint32_t i = 0; i < count; ++i) {
        if (masks[i] >= w.universe) throw std::invalid_argument("mask");
        if (w.equations % 64 &&
            coefficients[size_t(i) * w.limbs + w.limbs - 1] >> (w.equations % 64))
            throw std::invalid_argument("coefficient");
    }
}

static int check_basis(Workspace &w, const Rows &basis, uint32_t alive, Certificate *out)
{
    const auto n = w.n, universe = w.universe, blocks = w.blocks;
    const auto &low = w.low;
    const auto &roots = w.roots;
#include "build/basis_checks.inc"
}

extern "C" void *truth_create(uint32_t n, uint32_t equations)
{
    if (n < 1 || n > 20 || equations < 1 || equations > 128) return nullptr;
    try { return new Workspace(n, equations); }
    catch (const std::exception &) { return nullptr; }
}

extern "C" void truth_destroy(void *handle) { delete static_cast<Workspace *>(handle); }
extern "C" uint64_t truth_result_size() { return sizeof(Result); }

extern "C" int truth_certify(void *handle, const uint32_t *masks,
                             const uint64_t *coefficients, uint32_t count,
                             const uint32_t *basis_terms, uint32_t basis_size,
                             const uint32_t *offsets, uint32_t basis_count, Result *result)
{
    if (!result) return 6;
    *result = {};
    Certificate *out = &result->certificate;
    try {
        if (!handle) throw std::invalid_argument("handle");
        auto &w = *static_cast<Workspace *>(handle);
        validate(w, masks, coefficients, count);
        Rows basis = unpack(w.n, basis_terms, basis_size, offsets, basis_count, false);
        for (const auto &row : basis)
            if (row.empty() || std::adjacent_find(row.begin(), row.end()) != row.end())
                return out->code = 1;
        // No numerical value or root from a preceding target survives a call.
        std::fill(w.values.begin(), w.values.end(), 0);
        std::fill(w.roots.begin(), w.roots.end(), ~uint64_t(0));
        std::fill(w.present.begin(), w.present.end(), 0);
        if (w.n < 6) w.roots[0] = (uint64_t(1) << w.universe) - 1;
        result->scratch_bytes = 8 * (w.values.size() + w.roots.size()) + w.present.size();
        for (uint32_t i = 0; i < count; ++i) {
            const auto mask = masks[i];
            for (uint32_t limb = 0; limb < w.limbs; ++limb) {
                auto bits = coefficients[size_t(i) * w.limbs + limb];
                result->coefficient_bits += uint32_t(__builtin_popcountll(bits));
                while (bits) {
                    const auto equation = 64 * limb + uint32_t(__builtin_ctzll(bits));
                    w.values[size_t(equation) * w.blocks + (mask >> 6)] ^= w.low[mask & 63];
                    w.present[equation] = 1;
                    bits &= bits - 1;
                }
            }
        }
        uint32_t alive = w.universe;
        for (uint32_t equation = 0; equation < w.equations && alive; ++equation) {
            if (!w.present[equation]) continue;
            auto *values = w.values.data() + size_t(equation) * w.blocks;
            // At each stage, add the lower half of each block to its upper half.
            // Each word already contains direct evaluations of the low six bits.
            for (uint32_t half = 1; half < w.blocks; half <<= 1) {
                result->zeta_words += w.blocks / 2;
                for (uint32_t start = 0; start < w.blocks; start += 2 * half)
                    for (uint32_t j = 0; j < half; ++j)
                        values[start + half + j] ^= values[start + j];
            }
            alive = 0;
            for (uint32_t block = 0; block < w.blocks; ++block) {
                w.roots[block] &= ~values[block];
                alive += uint32_t(__builtin_popcountll(w.roots[block]));
            }
        }
        return check_basis(w, basis, alive, out);
    } catch (const std::invalid_argument &) { return out->code = 6; }
      catch (const std::exception &) { return out->code = 7; }
}

// A separate direct subset test for a supplied assignment. This never consults
// the truth table or certificate roots, including after a failed certification.
extern "C" int truth_evaluate(void *handle, const uint32_t *masks,
                              const uint64_t *coefficients, uint32_t count,
                              uint32_t assignment, uint64_t *out)
{
    if (!out) return 6;
    out[0] = out[1] = 0;
    try {
        if (!handle) throw std::invalid_argument("handle");
        const auto &w = *static_cast<Workspace *>(handle);
        if (assignment >= w.universe) throw std::invalid_argument("assignment");
        validate(w, masks, coefficients, count);
        for (uint32_t i = 0; i < count; ++i)
            if ((masks[i] & assignment) == masks[i])
                for (uint32_t limb = 0; limb < w.limbs; ++limb)
                    out[limb] ^= coefficients[size_t(i) * w.limbs + limb];
        return 0;
    } catch (const std::invalid_argument &) { return 6; }
      catch (const std::exception &) { return 7; }
}
